type RuntimeConfig = { anthropic: boolean; transcription: boolean; ffmpeg: boolean; mode: string; editor?: { engine: string; model: string; available: boolean }; engines?: { remotion?: { enabled: boolean; mode: string }; openchatcut?: { enabled: boolean; mode: string }; motionCanvas?: { enabled: boolean; mode: string } }; brollProviders?: { pexels: boolean; pixabay: boolean }; referenceStyle?: { enabled: boolean; stage: string; label: string; error?: string | null; engine?: string; capabilities: StyleRolloutCapabilities } };
type OpenChatCutProject = { id: string; name: string; updatedAt: number | null };
type BrollCandidate = { provider: "pexels" | "pixabay"; providerId: string; title: string; tags: string; previewUrl: string; downloadUrl: string; sourceUrl: string; creator: string; creatorUrl?: string; width: number; height: number; durationSeconds: number; licenseName: string; licenseUrl: string; score: number; match: { keyword: number; orientation: number; resolution: number; duration: number } };
type BrollSearchScene = { id: string; visualIntent: string; queries: string[]; candidates: BrollCandidate[]; errors: string[]; providerStatus: { pexels: string; pixabay: string } };
type BrollSearchResult = { orientation: string; scenes: BrollSearchScene[]; disclaimer: string };
type VisualEvent = { id: string; type: string; startMs?: number; endMs?: number; text?: string; subtext?: string; note?: string };
type Artifact = { name: string; url: string; streamUrl?: string; kind: string; engine?: string; createdBy?: string; version?: number; slot?: number; title?: string; width?: number; height?: number; durationMs?: number; stylePackId?: string; styleVersion?: number; generatedAt?: string };
type BrollEvent = { id: string; assetId: string; startMs: number; endMs: number; sourceStartMs: number };
type EditMessage = { id: string; role: "user" | "assistant"; text: string; timeMs?: number | null; rangeEndMs?: number | null; version?: number; turnId?: string; error?: boolean; createdAt?: string };
type EditTurn = { id: string; baseVersion: number; resultVersion: number; request: string; timeMs?: number | null; rangeEndMs?: number | null; status: string; error?: string; createdAt?: string; completedAt?: string };
type EditSession = { sessionId?: string | null; latestVersion: number; turnCount: number; status: string; summary?: string; messages: EditMessage[]; turns: EditTurn[] };
type TranscriptSegment = { id: string; startMs: number; endMs: number; text: string };
type MultiAsset = { id: string; filename: string; label: string; role: string; bytes?: number; expectedBytes?: number; durationMs: number; width: number; height: number; hasAudio: boolean; licenseConfirmed: boolean; status: string; analysisStatus: string; analysisError?: string; sha256?: string; visualEvidence?: { filename: string; keyframeTimesMs: number[]; width: number; height: number }; upload?: { totalBytes: number; receivedBytes: number } };
type MultiAssetClip = { id: string; sourceAssetId: string; sourceInMs: number; sourceOutMs: number; timelineStartMs: number; timelineEndMs: number; track: string; purpose: string; reason: string };
type MultiAssetPlan = { version: number; summary: string; storyBeats?: { title: string; purpose: string }[]; clips: MultiAssetClip[]; durationMs: number; confirmed: boolean; warnings?: { code: string; targetDurationMs?: number; plannedDurationMs?: number; deltaRatio?: number }[] };
type TranscriptProofreading = { status: "ready" | "needs_review" | "manual_review_required" | "confirmed"; model?: string | null; previewStale?: boolean; unresolved?: { segmentId: string; primaryText: string; secondaryText: string; reason: string }[]; changes?: { segmentId: string; before: string; after: string; evidence: string; reason: string }[]; manualCorrections?: { segmentId: string; before: string; after: string; reason: string }[]; confirmedUnresolvedSegmentIds?: string[] };
export type Project = { id: string; workflowMode?: "single-video-v1" | "multi-asset-v1"; multiAssetRevision?: number; status: string; goal: string; style: string; updatedAt?: string; brief?: { rawText: string; audience?: string; platform?: string; targetDurationMs?: number | null; aspectRatio?: "both" | "landscape" | "portrait"; mustUse?: string[]; mustAvoid?: string[] }; assets?: MultiAsset[]; assetAnalysis?: { status: string; completed?: number; failed?: number; currentAssetId?: string; currentStatus?: string }; multiAssetPlan?: MultiAssetPlan; multiAssetPlanHistory?: MultiAssetPlan[]; multiAssetPreview?: { planVersion: number; inputRevision: number; qc: { passed: boolean; profiles?: { id: string; probe: { width: number; height: number; durationMs: number }; passed: boolean }[] }; profiles?: { id: string; probe: { width: number; height: number; durationMs: number }; passed: boolean }[]; generatedAt?: string }; multiAssetPreviewReview?: { planVersion: number; inputRevision: number; profiles: string[]; reviewedAt: string } | null; transcription?: { status: string; model?: string | null; primary?: { status: string; provider?: string; error?: string }; secondary?: { status: string; provider?: string; model?: string; elapsedMs?: number; error?: string } }; primaryTranscript?: { provider: string; text: string; segments: TranscriptSegment[] } | null; secondaryTranscript?: { provider: string; model: string; text: string; segments: TranscriptSegment[] } | null; proofreading?: TranscriptProofreading | null; editSession?: EditSession | null; brollAssets?: { id: string; filename: string; durationMs: number; width: number; height: number; licenseConfirmed: boolean; sourceUrl?: string; licenseName?: string; licenseUrl?: string; provider?: string; sha256?: string }[]; editor?: { engine: string; model: string; version: number; phase: string; costUsd?: number; activity?: { at: string; tool?: string; message?: string }[] }; upload?: { filename: string; totalBytes: number; receivedBytes: number } | null; media?: { filename: string; durationMs: number; width: number; height: number; hasAudio: boolean; hasVideo: boolean }; music?: { filename: string; licenseConfirmed: boolean } | null; transcript?: { provider: string; text: string; segments: TranscriptSegment[] }; plan?: { summary: string; segments: { startMs: number; endMs: number; action: string; title: string; note: string }[]; shorts: { startMs: number; endMs: number; title: string }[]; visualEvents?: VisualEvent[]; brollEvents?: BrollEvent[]; stylePackId?: string; styleVersion?: number; styleParameters?: Record<string, string | number | boolean>; captionStyle?: Record<string, unknown>; layoutEvents?: { id: string; type: string; startMs: number; endMs: number; params?: Record<string, unknown> }[] }; stylePack?: StylePack | null; stylePackId?: string; styleVersion?: number; styleApplicationHash?: string; referenceStyleId?: string; styleCopy?: StyleCopy; styleParameters?: Record<string, string | number | boolean>; comments?: { timeMs: number; text: string; createdAt?: string }[]; artifacts?: (Artifact & { profile?: string; planVersion?: number; inputRevision?: number })[]; qc?: { passed: boolean; model?: string; version?: number; main?: { durationMs: number; width: number; height: number }; profiles?: { id: string; probe: { width: number; height: number; durationMs: number }; passed: boolean }[]; profileCount?: number; sourceAssetCount?: number; subtitlesBurnedIn?: boolean; subtitleTextChecked?: boolean; visualEventCountApplied?: number; brollEventCountApplied?: number; musicMixed?: boolean; hyperframesRendered?: boolean; audioVideoSyncChecked?: boolean; noUnexpectedBlackFrames?: boolean; visualReview?: { method: string; frames: { timeSeconds: number }[]; notes: string }; requiresHumanReview?: boolean }; error?: string; config?: RuntimeConfig };
type ProjectSummary = { id: string; status: string; goal: string; style: string; createdAt?: string; updatedAt?: string; error?: string | null; media?: { filename: string; durationMs: number; width?: number; height?: number } | null; latestVersion: number; hasTranscript: boolean; hasPlan: boolean; hasPreview: boolean; hasFinal: boolean };
type UploadProgress = { phase: "uploading" | "processing"; percent: number; receivedBytes: number; totalBytes: number } | null;
const DEFAULT_GOAL = "把这条口播剪成一条有清晰 Hook、3 个视觉强调点和结尾 CTA 的短视频。";
const CHRISTIAN_STYLE = "Christian Peverelli / Hybrid post-production";
const CHRISTIAN_RECIPE = `请按 Christian Peverelli / WeAreNoCode 在《I Fully Automated My Video Editing Using Claude Code》中展示的混合后期思路剪辑这条视频。以真实素材和转录为依据，不编造画面、台词或事实。\n\n执行步骤：\n1. 先检查视频、音频、时长、画幅和转录；保留语义完整的句子，删除停顿、口误和重录。\n2. 依据转录安排清晰 Hook、节奏紧凑的主体、关键视觉强调和结尾 CTA；所有标题与强调必须和实际台词同步。\n3. 优先使用用户上传且已确认有权使用的 B-roll；Claude 从真实可用素材中选择画面和源时间点，FFmpeg 按计划切入主片与适用的 Shorts，并保留口播原声。没有上传素材时不要伪造 B-roll。\n4. 在当前网站支持范围内生成标题卡、重点强调、字幕、配乐、主片和 5 条竖屏 Shorts，并在预览/批注后再渲染。\n5. 渲染后检查时长、音画同步、持续黑帧、字幕可读性、B-roll 执行数和导出文件；发现问题时说明并修正，不要把未完成标成通过。\n6. 如当前环境确实接入外部工具，可选用 Chrome 检索并取得有权使用的素材、HyperFrames 制作 HTML 动效、Tella 录制素材、Epidemic Sound 添加已授权音乐/音效。未接入或未授权时跳过并明确说明。\n\n视觉风格：品牌颜色、字体、转场和声音偏好优先沿用用户素材/项目设置；没有提供时保持克制、清晰、适合 YouTube 口播的编辑风格。交付前列出实际执行步骤、跳过的外部依赖和 QC 结果。`;
const API_BASE = import.meta.env.VITE_API_BASE ?? "/wayne-api";
const isLoopbackPortal = typeof window !== "undefined" && ["localhost", "127.0.0.1", "::1"].includes(window.location.hostname);
const stageIds = ["start", "creating", "review"] as const;
type Stage = typeof stageIds[number];
const stageLabels = [{ id: "start", label: "准备素材" }, { id: "creating", label: "自动制作" }, { id: "review", label: "审核与导出" }];
async function apiJson(path: string, options: RequestInit = {}) { const response = await fetch(`${API_BASE}${path}`, options); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || `请求失败 (${response.status})`); return data as Project; }
function userError(error: unknown, fallback: string) { const message = error instanceof Error ? error.message : String(error || ""); return /load failed|failed to fetch|networkerror/i.test(message) ? "上传连接中断，已保留已完成分块，请重新点击继续上传" : message || fallback; }
function ms(value = 0) { const total = Math.max(0, Math.round(value / 1000)); return `${String(Math.floor(total / 60)).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`; }
function stageFor(project?: Project): Stage { if (!project) return "start"; if (project.workflowMode === "multi-asset-v1" && project.multiAssetPlan) return "review"; if (reviewState(project).video || ["plan_ready", "plan_confirmed", "preview_ready", "awaiting_revision", "chat_editing", "chat_ready", "rendering", "rendering_preview", "completed"].includes(project.status)) return "review"; return project.media || project.assets?.length || project.error ? "creating" : "start"; }
function workflowStatus(project?: Project | null) { if (!project) return "选择一种剪辑方式开始"; if (project.error) return reviewState(project).video ? "本轮制作未完成，上一版仍可查看" : "本轮制作未完成，项目已保留"; return ({ created: "等待上传素材", uploading_assets: "正在上传多段素材", assets_ready: "素材已上传，等待分析", analyzing_assets: "正在逐条分析素材", transcript_ready: project.workflowMode === "multi-asset-v1" ? "素材分析完成，准备生成方案" : "转录完成，准备生成草剪", transcribing: "正在识别口播内容", planning: project.workflowMode === "multi-asset-v1" ? "Claude 正在编排故事线" : "正在生成并检查草剪", plan_ready: project.workflowMode === "multi-asset-v1" ? "方案已生成，请检查并确认" : "草剪已准备好，请审阅", plan_confirmed: "方案已确认，等待预览", rendering_preview: "正在生成横竖屏预览", preview_ready: project.workflowMode === "multi-asset-v1" ? "预览已生成，请播放检查后导出" : "草剪已准备好，请审阅", awaiting_revision: "批注已保存，可重新生成草剪或导出", rendering: "正在导出并检查成片", completed: project.workflowMode === "multi-asset-v1" ? "横屏与竖屏成片已完成" : "成片已完成，可下载", chat_editing: "正在制作新版本", chat_ready: "新版本已生成，可以继续对话调整" } as Record<string, string>)[project.status] || "项目已保存，可以继续处理"; }
function stageHint(stage: Stage) { return ({ start: "上传素材", creating: "转录与生成", review: "看视频、提修改", rendered: "下载与验收", conversation: "继续修改" } as Record<Stage, string>)[stage]; }
function phaseLabel(status?: string) { return ({ created: "等待开始", inspecting: "正在检查视频", uploading_assets: "正在上传素材", analyzing_assets: "正在分析素材", assets_ready: "素材已上传", transcribing: "正在转录", transcript_ready: "素材分析完成", planning: "正在生成草剪或方案", plan_ready: "方案待确认", plan_confirmed: "等待预览", rendering_preview: "正在生成预览", preview_ready: "预览待检查", awaiting_revision: "等待你的批注", rendering: "正在导出", completed: "已完成", chat_editing: "正在修改", chat_ready: "修改完成", failed: "需要重试", needs_input: "需要处理" } as Record<string, string>)[status || ""] || "未开始"; }
function estimatedWait(project?: Project | null) { if (project?.error) return "可以继续本项目"; if (!project) return "通常 3–8 分钟"; if (["transcribing", "inspecting", "analyzing_assets"].includes(project.status)) return "通常 1–3 分钟"; if (["planning", "rendering_preview"].includes(project.status)) return "通常 4–12 分钟"; if (project.status === "rendering") return "通常 2–8 分钟"; if (project.status === "chat_editing") return "通常 2–6 分钟"; return ["completed"].includes(project.status) ? "成片可下载" : "等待你的操作"; }
function isRecoverableError(project?: Project | null) { return Boolean(project?.error && ["needs_input", "failed"].includes(project.status)); }
function formatBytes(bytes = 0) { if (bytes < 1024 * 1024) return `${Math.max(0, Math.round(bytes / 1024))} KB`; return `${(bytes / 1024 / 1024).toFixed(1)} MB`; }
function historyStatus(item: ProjectSummary) { if (item.error) return "需要处理"; return ({ created: "待上传", inspecting: "检查中", transcribing: "转录中", transcript_ready: "待生成草剪", planning: "生成中", plan_ready: "待审阅", preview_ready: "待审阅", awaiting_revision: "等待修订", rendering: "导出中", completed: "已完成", chat_editing: "修改中", chat_ready: "有新版本", failed: "可恢复" } as Record<string, string>)[item.status] || "已保存"; }
function relativeDate(value?: string) { if (!value) return "刚刚"; const delta = Math.max(0, Date.now() - new Date(value).getTime()); const minutes = Math.floor(delta / 60000); if (minutes < 1) return "刚刚"; if (minutes < 60) return `${minutes} 分钟前`; const hours = Math.floor(minutes / 60); if (hours < 24) return `${hours} 小时前`; return `${Math.floor(hours / 24)} 天前`; }

function MultiAssetReview({ project, apiBase, busy, message, onConfirm, onRegenerate, onRestore, onUpdateAsset, onReviewPreview, onGenerate, onPreview, onExport }: { project: Project; apiBase: string; busy: boolean; message: string; onConfirm: (version: number) => void; onRegenerate: (request: string) => void; onRestore: (version: number) => void; onUpdateAsset: (assetId: string, changes: Partial<Pick<MultiAsset, "role" | "label" | "licenseConfirmed">>) => void; onReviewPreview: (profiles: string[]) => void; onGenerate: () => void; onPreview: () => void; onExport: () => void }) {
  const [request, setRequest] = useState("");
  const plan = project.multiAssetPlan;
  const isCurrentArtifact = (artifact: NonNullable<Project["artifacts"]>[number]) => artifact.planVersion === plan?.version && artifact.inputRevision === Number(project.multiAssetRevision || 0);
  const allVideos = (project.artifacts || []).filter((artifact) => artifact.kind === "video" && artifact.profile);
  const videos = allVideos.filter(isCurrentArtifact);
  const historicVideos = allVideos.filter((artifact) => !isCurrentArtifact(artifact));
  const allPreviews = (project.artifacts || []).filter((artifact) => artifact.kind === "preview" && artifact.profile);
  const previews = allPreviews.filter(isCurrentArtifact);
  const historicPreviews = allPreviews.filter((artifact) => !isCurrentArtifact(artifact));
  const previewReady = Boolean(project.multiAssetPreview?.qc.passed && project.multiAssetPreview.planVersion === plan?.version && project.multiAssetPreview.inputRevision === Number(project.multiAssetRevision || 0));
  const currentReview = project.multiAssetPreviewReview;
  const reviewedProfiles = currentReview && currentReview.planVersion === plan?.version && Number(currentReview.inputRevision) === Number(project.multiAssetRevision || 0) ? currentReview.profiles : [];
  const allPreviewsReviewed = Boolean(project.multiAssetPreview?.profiles?.length && project.multiAssetPreview.profiles.every((item) => reviewedProfiles?.includes(item.id)));
  const assets = new Map((project.assets || []).map((asset) => [asset.id, asset]));
  return <div className="multi-review">
    <div className="panel-header"><div><p className="eyebrow">03 / 检查与导出</p><h3>{videos.length ? "正式成片已生成" : previewReady ? "请检查横竖屏预览" : plan?.confirmed ? "方案已确认，先生成预览" : "检查故事线和素材来源"}</h3></div><span className={`soft-tag ${project.qc?.passed || previewReady ? "success" : ""}`}>{project.qc?.passed ? "最终 QC 通过" : previewReady ? "预览 QC 通过" : plan?.confirmed ? "待预览" : "待确认"}</span></div>
    {plan && <>
      <div className="multi-plan-summary"><strong>{plan.summary}</strong><span>目标时长 {ms(project.brief?.targetDurationMs || 0)} · 预计成片 {ms(plan.durationMs)} · 方案 v{plan.version}</span></div>
      {plan.warnings?.map((warning) => warning.code === "duration-target-exceeded" ? <div className="multi-plan-warning" key={warning.code}>预计时长 {ms(warning.plannedDurationMs || plan.durationMs)} 与目标 {ms(warning.targetDurationMs || project.brief?.targetDurationMs || 0)} 相差约 {Math.round((warning.deltaRatio || 0) * 100)}%。这是软目标；请检查节奏是否符合你的方案。</div> : null)}
      <details className="multi-assets-review"><summary>素材与授权（{project.assets?.length || 0}）</summary><div className="asset-status-list">{(project.assets || []).map((asset) => <article key={asset.id} className="asset-status-row"><span className={`asset-state-dot ${asset.analysisStatus}`} /><div><strong>{asset.label || asset.filename}</strong><small>{asset.filename} · {ms(asset.durationMs)}</small>{asset.visualEvidence && <img className="asset-contact-sheet" loading="lazy" src={`${apiBase}/api/projects/${project.id}/assets/${asset.id}/contact-sheet`} alt={`${asset.label} 的早、中、晚关键帧`} />}<div className="asset-edit-controls"><label>用途<select disabled={busy} value={asset.role} onChange={(event) => onUpdateAsset(asset.id, { role: event.target.value })}><option value="main">主素材</option><option value="supporting">补充镜头</option><option value="broll">B-roll</option><option value="voiceover">含口播的视频</option></select></label><label className="asset-license-toggle"><input type="checkbox" disabled={busy} checked={asset.licenseConfirmed} onChange={(event) => onUpdateAsset(asset.id, { licenseConfirmed: event.target.checked })} />已确认使用许可</label></div></div></article>)}</div></details>
      {(project.multiAssetPlanHistory || []).length > 0 && <label className="multi-history-select">历史方案<select disabled={busy} value="" onChange={(event) => { const version = Number(event.target.value); if (version) onRestore(version); }}><option value="">恢复旧方案…</option>{[...(project.multiAssetPlanHistory || [])].reverse().map((item) => <option key={item.version} value={item.version}>v{item.version} · {item.summary}</option>)}</select></label>}
      <div className="multi-timeline-list">{plan.clips.map((clip, index) => <article className="multi-timeline-clip" key={clip.id}><span className="clip-number">{String(index + 1).padStart(2, "0")}</span><div className="clip-main"><strong>{clip.purpose || "内容片段"} · {assets.get(clip.sourceAssetId)?.label || assets.get(clip.sourceAssetId)?.filename || clip.sourceAssetId}</strong><small>源片 {ms(clip.sourceInMs)}–{ms(clip.sourceOutMs)} → 成片 {ms(clip.timelineStartMs)}–{ms(clip.timelineEndMs)}</small><p>{clip.reason}</p><button type="button" className="text-button" disabled={busy} onClick={() => setRequest(`调整成片 ${ms(clip.timelineStartMs)}–${ms(clip.timelineEndMs)} 的镜头（当前来源：${assets.get(clip.sourceAssetId)?.label || assets.get(clip.sourceAssetId)?.filename}，原片 ${ms(clip.sourceInMs)}–${ms(clip.sourceOutMs)}）：`)}>修改此镜头</button></div></article>)}</div>
      {project.assets?.some((asset) => !asset.licenseConfirmed) && <div className="api-alert"><strong>还有素材未确认使用许可，正式导出会被阻止。</strong></div>}
      {!plan.confirmed && <div className="multi-plan-actions"><button className="continue-button" type="button" disabled={busy} onClick={() => onConfirm(plan.version)}>确认方案并继续 <Check size={17} /></button><label><span>可选：要求 Claude 调整方案</span><textarea value={request} onChange={(event) => setRequest(event.target.value)} rows={2} placeholder="例如：把产品演示提前，缩短开场" /></label><button className="secondary-button" type="button" disabled={busy || !request.trim()} onClick={() => onRegenerate(request.trim())}>重新生成方案</button></div>}
      {plan.confirmed && <div className="multi-plan-actions">{previewReady ? <><p className="human-review-prompt">逐个播放横屏和竖屏预览，确认镜头、字幕和声音后勾选检查状态。</p><button className="continue-button" type="button" disabled={busy || project.assets?.some((asset) => !asset.licenseConfirmed) || !allPreviewsReviewed} onClick={onExport}>{busy ? "正在生成正式成片…" : "检查通过，导出正式成片"} <ChevronRight size={18} /></button></> : <button className="continue-button" type="button" disabled={busy || project.assets?.some((asset) => !asset.licenseConfirmed)} onClick={onPreview}>{busy ? "正在生成预览…" : "生成横屏和竖屏预览"} <ChevronRight size={18} /></button>}<label><span>调整已确认方案</span><textarea value={request} onChange={(event) => setRequest(event.target.value)} rows={2} placeholder="例如：用产品演示替换第二段素材" /></label><button className="secondary-button" type="button" disabled={busy || !request.trim()} onClick={() => onRegenerate(request.trim())}>生成新方案版本</button></div>}
    </>}
    {!plan && project.assetAnalysis?.status === "ready" && <button type="button" className="continue-button" disabled={busy} onClick={onGenerate}>重新生成方案 <ChevronRight size={18} /></button>}
    {previews.length > 0 && <><div className="multi-section-label"><strong>低分辨率审阅预览</strong><span>当前方案 v{plan?.version} · 播放检查镜头顺序、字幕与声音</span></div><div className="multi-output-grid">{previews.map((artifact) => <article className="multi-output-card" key={artifact.name}><div><strong>{artifact.profile === "portrait" ? "竖屏预览" : "横屏预览"}</strong><small>{artifact.width} × {artifact.height} · {ms(artifact.durationMs || 0)}</small></div><video controls playsInline preload="metadata" src={`${apiBase}${artifact.streamUrl || artifact.url}`} /><a className="secondary-button" href={`${apiBase}${artifact.url}`}>下载预览</a><label className="preview-reviewed-check"><input type="checkbox" disabled={busy || !previewReady} checked={Boolean(reviewedProfiles?.includes(artifact.profile || ""))} onChange={(event) => { const next = new Set(reviewedProfiles || []); if (event.target.checked && artifact.profile) next.add(artifact.profile); else if (artifact.profile) next.delete(artifact.profile); onReviewPreview([...next]); }} />我已完整播放并检查此预览</label></article>)}</div></>}
    {historicPreviews.length > 0 && <details className="multi-history-output"><summary>历史方案预览（{historicPreviews.length}）</summary><div className="multi-output-grid">{historicPreviews.map((artifact) => <article className="multi-output-card" key={artifact.name}><div><strong>{artifact.profile === "portrait" ? "历史竖屏预览" : "历史横屏预览"} · 方案 v{artifact.planVersion}</strong><small>{artifact.width} × {artifact.height} · {ms(artifact.durationMs || 0)}</small></div><video controls playsInline preload="metadata" src={`${apiBase}${artifact.streamUrl || artifact.url}`} /><a className="secondary-button" href={`${apiBase}${artifact.url}`}>下载历史预览</a></article>)}</div></details>}
    {previewReady && <div className="multi-qc-card passed"><strong>横竖屏预览均通过自动检查</strong><span>检查镜头画面、字幕和声音后再导出正式分辨率成片。</span></div>}
    {videos.length > 0 && <div className="multi-output-grid">{videos.map((artifact) => <article className="multi-output-card" key={artifact.name}><div><strong>{artifact.profile === "portrait" ? "竖屏成片" : "横屏成片"}</strong><small>{artifact.width} × {artifact.height} · {ms(artifact.durationMs || 0)} · v{artifact.version}</small></div><video controls playsInline preload="metadata" src={`${apiBase}${artifact.streamUrl || artifact.url}`} /><a className="secondary-button" href={`${apiBase}${artifact.url}`}>下载{artifact.profile === "portrait" ? "竖屏" : "横屏"} MP4</a></article>)}</div>}
    {historicVideos.length > 0 && <details className="multi-history-output"><summary>历史正式成片（{historicVideos.length}）</summary><div className="multi-output-grid">{historicVideos.map((artifact) => <article className="multi-output-card" key={artifact.name}><div><strong>{artifact.profile === "portrait" ? "历史竖屏成片" : "历史横屏成片"} · 方案 v{artifact.planVersion}</strong><small>{artifact.width} × {artifact.height} · {ms(artifact.durationMs || 0)} · 渲染 v{artifact.version}</small></div><video controls playsInline preload="metadata" src={`${apiBase}${artifact.streamUrl || artifact.url}`} /><a className="secondary-button" href={`${apiBase}${artifact.url}`}>下载历史 MP4</a></article>)}</div></details>}
    {project.qc && <div className={`multi-qc-card ${project.qc.passed ? "passed" : "failed"}`}><strong>{project.qc.passed ? "横竖屏输出均通过自动检查" : "自动检查发现问题"}</strong><span>{project.qc.sourceAssetCount || plan?.clips.length || 0} 个镜头来源 · {project.qc.profileCount || videos.length} 种画幅 · 最终发布前请完整观看成片</span></div>}
    {message && <div className="api-alert"><strong>{message}</strong></div>}
  </div>;
}

